import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.Bqa2y7hU.js";const u=JSON.parse('{"title":"为什么是 Xiaoyi_QQ_V4","description":"Xiaoyi_QQ_V4 是什么、适合谁、由哪几部分组成、和常见机器人框架的区别。","frontmatter":{"title":"为什么是 Xiaoyi_QQ_V4","description":"Xiaoyi_QQ_V4 是什么、适合谁、由哪几部分组成、和常见机器人框架的区别。"},"headers":[],"relativePath":"guide/what-is.md","filePath":"guide/what-is.md","lastUpdated":1789790467000}'),n={name:"guide/what-is.md"};function o(l,t,d,r,p,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="为什么是-xiaoyi-qq-v4" tabindex="-1">为什么是 Xiaoyi_QQ_V4 <a class="header-anchor" href="#为什么是-xiaoyi-qq-v4" aria-label="Permalink to &quot;为什么是 Xiaoyi_QQ_V4&quot;">​</a></h1><p>Xiaoyi_QQ_V4 是一套<strong>自托管的 QQ 机器人框架</strong>：你自己在服务器上跑起来，接上 QQ 官方机器人或 OneBot 11 实现端，然后通过网页控制台管理机器人、安装插件、查看运行数据。</p><p>这页讲清楚三件事：它由什么组成、能做什么、以及为什么这样设计。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>一句话：<strong>一个可执行文件 + 一个数据库，就是一套完整的机器人平台。</strong></p><table tabindex="0"><thead><tr><th>组成部分</th><th>说明</th></tr></thead><tbody><tr><td>框架本体</td><td>单个 C++ 可执行文件，包含管理接口、适配器、插件运行时与前端页面</td></tr><tr><td>数据库</td><td>一个 PostgreSQL 实例，保存用户、机器人、插件绑定、消息记录等业务数据</td></tr><tr><td>控制台</td><td>内嵌在框架里的网页界面，默认监听 <code>8080</code> 端口</td></tr><tr><td>插件</td><td>独立的 <code>.so</code> 文件，在框架进程内运行，可单独安装到某台机器人</td></tr><tr><td>云编译服务（可选）</td><td>独立的小程序，把插件源码编译成可上架的插件包，供不会配编译环境的用户自助打包</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">不需要的东西</p><p>不需要 Redis、不需要消息队列、不需要单独部署前端、不需要 Node.js 运行时。</p></div><h2 id="它由哪几部分组成" tabindex="-1">它由哪几部分组成 <a class="header-anchor" href="#它由哪几部分组成" aria-label="Permalink to &quot;它由哪几部分组成&quot;">​</a></h2><p>从使用者角度看，只有三层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        浏览器</span></span>
<span class="line"><span>           │  管理控制台（用户 / 管理员）</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>   Xiaoyi_QQ_V4 框架进程</span></span>
<span class="line"><span>     ├── 管理面      配置、插件市场、订阅、日志</span></span>
<span class="line"><span>     ├── 适配器      QQ 官方 / OneBot 11 的连接与收发</span></span>
<span class="line"><span>     └── 插件运行时   加载 .so，把事件分发给插件</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>      PostgreSQL</span></span></code></pre></div><p><strong>事件是怎么流动的</strong>（以一条群消息为例）：</p><ol><li>适配器从平台收到消息；</li><li>框架把不同平台的消息<strong>归一化成统一事件</strong>，插件只面对这一种结构，不需要为每个平台写一套代码；</li><li>事件按优先级依次交给该机器人已启用的插件，插件可以选择回复、改写、拦截或什么都不做；</li><li>插件要发消息时，调用<strong>统一的发送接口</strong>，由适配器翻译成对应平台的格式发出去。</li></ol><p>插件开发者只需要理解第 2–4 步，不用关心平台差异。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li><strong>接机器人</strong>：QQ 官方机器人（Webhook 或 WebSocket 网关）与 OneBot 11（反向 WebSocket）。创建后立即生效，不用重启服务。</li><li><strong>装插件</strong>：从插件市场一键安装到某台机器人，可启停、可调优先级、可单独开关拦截能力。</li><li><strong>管社群</strong>：内置的群管插件提供违禁词、链接/卡片/转发拦截、刷屏检测、禁言踢人、入群验证与入群审批。</li><li><strong>看数据</strong>：机器人状态、消息记录、运行日志、服务器监控都在网页里，不需要登服务器看后台日志。</li><li><strong>做定制</strong>：插件可以用 C++ 写，自带 Web 配置面板，也能调用平台的禁言、踢人、审批等能力。</li><li><strong>商业化</strong>（如果你对外提供服务）：套餐订阅、卡密兑换、余额充值、支付对接。</li></ul><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><p><strong>适合你，如果：</strong></p><ul><li>想自己完全掌控机器人和数据，不喜欢把机器人托管在别人的平台上；</li><li>需要同时管理多台机器人，或者要给不同的人分配不同的机器人；</li><li>有定制需求，愿意写（或找人写）C++ 插件；</li><li>想要一套开箱即用的社群管理能力，而不是从零拼插件。</li></ul><p><strong>可能不适合你，如果：</strong></p><ul><li>只想跑一个单群小机器人、且不想碰服务器 —— 更轻量的本地框架会更省事；</li><li>只接非 QQ 平台 —— 本框架目前的适配器专注 QQ。</li></ul><h2 id="和其他机器人框架的区别" tabindex="-1">和其他机器人框架的区别 <a class="header-anchor" href="#和其他机器人框架的区别" aria-label="Permalink to &quot;和其他机器人框架的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>常见做法</th><th>Xiaoyi_QQ_V4 的选择</th></tr></thead><tbody><tr><td>部署</td><td>需要 Python 运行时 + 若干依赖包</td><td>单个二进制，除数据库外无依赖</td></tr><tr><td>插件</td><td>脚本语言，改完要重启</td><td>C++ 动态库，只增不改的稳定接口</td></tr><tr><td>多机器人</td><td>一个实例跑一个机器人</td><td>一个实例管多台，控制台里按机器人隔离数据</td></tr><tr><td>插件配置</td><td>改配置文件</td><td>插件自带网页面板，在控制台里点开就用</td></tr><tr><td>平台差异</td><td>插件里写 <code>if 平台 == ...</code></td><td>框架统一成一套事件与调用接口</td></tr></tbody></table><p>代价也要说清楚：<strong>插件是编译型的</strong>，改一行代码要重新编译再上传（可以用在线云编译服务）；并且由于是原生程序，插件写崩溃时会影响框架进程，写插件时要注意异常处理。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/guide/features">核心特性</a>：逐项展开上面提到的能力</li><li><a href="/RuaBot.Doc/guide/requirements">系统要求</a>：需要什么样的服务器</li><li><a href="/RuaBot.Doc/deploy/install">安装</a>：把它跑起来</li></ul>`,25)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
